 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    # Find color components whose bounding boxes are dense rectangular objects.
    for color in {v for row in grid for v in row if v != bg}:
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r,c) in seen: continue
                q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                            seen.add((yy,xx)); q.append((yy,xx))
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                area=(y1-y0+1)*(x1-x0+1)
                if area >= 4 and len(cells)/area >= 0.55:
                    for y in range(y0,y1+1):
                        for x in range(x0,x1+1): out[y][x]=color
    # Everything not explained by a dense colored rectangle is stray noise.
    for r in range(h):
        for c in range(w):
            if out[r][c] == grid[r][c] and grid[r][c] != bg:
                out[r][c]=bg
    return out

